D="$(cd "$(dirname "$0")/.." && pwd)"
N=$1; W=$2; H=${3:-900}; S=${4:-}
rm -f "$D/.shots/$N"*.png
timeout 90 env HOME=$TMPDIR firefox --headless --no-remote --profile $TMPDIR/ffp --window-size=$W,$H --screenshot "$D/.shots/$N.png" "file://$D/index.html$S" >/dev/null 2>&1
magick "$D/.shots/$N.png" -crop ${W}x1000 +repage "$D/.shots/${N}_%d.png"
ls "$D/.shots" | grep "^$N"
E
