harness='''
<script>
window.addEventListener('load', function () {
  var q = location.search.slice(1);
  var $ = function (id) { return document.getElementById(id); };
  var input = $('email'), form = $('signup'), error = $('email-error');
  function type(v) { input.value = v; input.dispatchEvent(new Event('input', {bubbles: true})); }
  if (q === 'error') { input.focus(); type('imani@margin'); form.requestSubmit(); $('subscribe').scrollIntoView(); return; }
  if (q === 'success') { type('imani.vale@margin.example'); form.requestSubmit(); $('subscribe').scrollIntoView(); return; }
  if (q === 'focus') { document.querySelector('input[value=night]').focus(); return; }
  var out = [];
  function ok(name, cond, extra) { out.push((cond ? 'PASS ' : 'FAIL ') + name + (cond ? '' : ' :: ' + extra)); }
  var root = document.documentElement;
  var radios = document.querySelectorAll('input[name="reading-mode"]');
  ok('initial mode follows system (night)', root.dataset.mode === 'night' && radios[1].checked, root.dataset.mode);
  radios[0].click();
  ok('click Paper -> paper', root.dataset.mode === 'paper', root.dataset.mode);
  var st; try { st = localStorage.getItem('margin.reading-mode'); } catch (e) { st = 'ERR ' + e; }
  ok('saved paper', st === 'paper', st);
  ok('theme-color updated', document.querySelector('meta[name=theme-color]').content === '#f0eadd', '');
  ok('paper bg applied', getComputedStyle(document.body).backgroundColor !== '', getComputedStyle(document.body).backgroundColor);
  out.push('INFO bg=' + getComputedStyle(root).getPropertyValue('--paper'));
  radios[1].click();
  ok('click Night -> night', root.dataset.mode === 'night' && !radios[0].checked, root.dataset.mode);
  out.push('INFO bg=' + getComputedStyle(root).getPropertyValue('--paper'));
  try { localStorage.removeItem('margin.reading-mode'); } catch (e) {}

  ok('novalidate set', form.noValidate, '');
  ok('error hidden at start', error.hidden, '');
  type('typing'); ok('quiet while typing first time', error.hidden, error.textContent);
  type('');
  form.requestSubmit();
  ok('empty submit -> message', !error.hidden && error.textContent === 'Enter your email address.', error.textContent);
  ok('aria-invalid', input.getAttribute('aria-invalid') === 'true', '');
  ok('describedby error', input.getAttribute('aria-describedby').indexOf('email-error') === 0, input.getAttribute('aria-describedby'));
  ok('focus on input', document.activeElement === input, document.activeElement && document.activeElement.tagName);
  type('foo'); ok('missing @', /missing an @/.test(error.textContent), error.textContent);
  type('foo@bar'); ok('unfinished domain', /Finish the part after/.test(error.textContent), error.textContent);
  type('a b@c.de'); ok('spaces', /spaces/.test(error.textContent), error.textContent);
  type('a@@b.com'); ok('two @', /more than one/.test(error.textContent), error.textContent);
  type('@b.com'); ok('no local part', /before the @/.test(error.textContent), error.textContent);
  type('a@b..com'); ok('double dot', !error.hidden, '');
  type('a@.com'); ok('leading dot domain', !error.hidden, '');
  type('a@b.com.'); ok('trailing dot', !error.hidden, '');
  type('  foo@bar.co  '); ok('valid clears error', error.hidden && !input.hasAttribute('aria-invalid') && input.dataset.valid === 'true', error.textContent);
  ok('describedby back to hint', input.getAttribute('aria-describedby') === 'email-hint', '');
  form.requestSubmit();
  ok('success shown', $('signup-fields').hidden && !$('signup-done').hidden, '');
  ok('address echoed trimmed', $('signup-address').textContent === 'foo@bar.co', $('signup-address').textContent);
  ok('focus on confirmation', document.activeElement === $('signup-done'), '');
  ok('url unchanged (no submission)', location.search === '?tests', location.search);
  $('signup-reset').click();
  ok('reset restores form', !$('signup-fields').hidden && $('signup-done').hidden && input.value === '' && document.activeElement === input, '');
  ok('reset clears state', error.hidden && !input.dataset.valid, '');
  type('nope'); ok('quiet again after reset', error.hidden, '');
  input.dispatchEvent(new Event('blur')); ok('blur validates', !error.hidden, '');
  type('');
  window.scrollTo(0, document.documentElement.scrollHeight);
  setTimeout(function () {
    var r = parseFloat(getComputedStyle(root).getPropertyValue('--read'));
    ok('gauge progress at bottom ~1', r > 0.98, r);
    out.push('INFO overflowX=' + (document.documentElement.scrollWidth > window.innerWidth) + ' sw=' + document.documentElement.scrollWidth + ' iw=' + window.innerWidth);
    window.scrollTo(0, 0);
    var pre = document.createElement('pre');
    pre.style.cssText = 'position:absolute;top:0;left:0;right:0;z-index:99;margin:0;padding:12px;background:#fff;color:#000;font:12px/1.4 monospace;white-space:pre-wrap';
    pre.textContent = out.join('\\n');
    document.body.appendChild(pre);
  }, 400);
});
</script>
</body>'''
s=s.replace('</body>',harness)
open('.shots/harness.html','w').write(s)
E
cd .shots
