python3 - <<'E'
p='index.html'; s=open(p).read()
for old,new in [
 ('A Language for Empty&nbsp;Pools','A Language for Empty Pools'),
 ('<ol class="archive__list" reversed start="13">','<ul class="archive__list">'),
 ('            </li>\n          </ol>','            </li>\n          </ul>'),
]:
    assert old in s, old
    s=s.replace(old,new)
open(p,'w').write(s)
p='styles.css'; s=open(p).read()
old='''.signup__input::placeholder {
  color: var(--ink-soft);
  opacity: 0.75;'''
assert old in s
s=s.replace(old,'''.signup__input::placeholder {
  color: var(--ink-soft);
  opacity: 1;''')
old='''  font-size: clamp(1.875rem, 3.6vw, 2.875rem);'''
assert old in s
s=s.replace(old,'''  font-size: clamp(1.75rem, 3.6vw, 2.875rem);''')
open(p,'w').write(s)

# sanity: tag balance
from html.parser import HTMLParser
void={'meta','link','input','br','img','hr','base','path','circle'}
class P(HTMLParser):
    def __init__(s): super().__init__(); s.st=[]; s.ids=[]; s.err=[]
    def handle_starttag(s,t,a):
        d=dict(a)
        if 'id' in d: s.ids.append(d['id'])
        if t not in void: s.st.append(t)
    def handle_startendtag(s,t,a):
        d=dict(a)
        if 'id' in d: s.ids.append(d['id'])
    def handle_endtag(s,t):
        if not s.st or s.st[-1]!=t: s.err.append((t,s.st[-3:], s.getpos()))
        else: s.st.pop()
h=open('index.html').read(); q=P(); q.feed(h)
print('unclosed',q.st,'errors',q.err[:5]); 
import re,collections
print('dup ids',[k for k,v in collections.Counter(q.ids).items() if v>1])
refs=set(re.findall(r'(?:href="#|aria-labelledby="|aria-describedby="|for=")([\w-]+)',h))
print('missing refs',[r for r in refs if r not in q.ids])
print('external refs',re.findall(r'(?:https?:)?//[^\s"\']+',h+open('styles.css').read()+open('app.js').read()))
E
node --check app.js && echo JS_OK
